  await page.keyboard.press("Tab");
  await expect(page.getByRole("link", { name: "Skip to content" })).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(page.locator("#landing")).toBeFocused();
  await page.getByRole("link", { name: "Methodology", exact: true }).click();
  await expect(page).toHaveURL(/\/methodology$/u);
  await expect(page).toHaveTitle("Methodology · Exposed");
  await expect(page.getByRole("link", { name: "official Register of Members' Financial Interests" })).toHaveAttribute("href", /parliament.uk/u);
  await page.goto("/methodology");
  await page.keyboard.press("Tab");
  await page.keyboard.press("Enter");
  await expect(page.locator("#methodology")).toBeFocused();
  await page.getByRole("link", { name: "Exposed home" }).click();
  await page.getByRole("link", { name: "Search MPs and funders" }).click();
  await expect(page).toHaveURL(/\/search$/u);
  await expect(page.getByRole("searchbox")).toHaveValue("");
  expect(requests).toEqual([]);
});

for (const viewport of [{ width: 1440, height: 900 }, { width: 390, height: 844 }]) {
  test(`landing fits ${viewport.width}px viewport`, async ({ page }) => {
    await page.setViewportSize(viewport);
    await page.goto("/");
    await page.evaluate(() => document.fonts.ready);
    expect(await page.evaluate(() => ({ width: document.documentElement.scrollWidth, height: document.documentElement.scrollHeight }))).toEqual(viewport);
    for (const link of await page.locator("#landing a").all()) {
      const bounds = await link.boundingBox();
      expect(bounds?.height).toBeGreaterThanOrEqual(44);
    }
    await page.locator("#landing").evaluate((main) => { main.style.fontSize = "200%"; });
    expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBe(viewport.width);
  });
}

for (const query of ["?q=", "?strictness=0.42", "?q=Example&strictness=0.42&extra=&q=second", "?q=&strictness=&extra=%20"]) {
  test(`legacy root preserves ${query} without JavaScript`, async ({ browser, baseURL, backend, request }) => {
    await backend.route("**/api/search?*", (route) => route.fulfill({ json: { entities: [] } }));
    const response = await request.get(`/${query}`, { maxRedirects: 0 });
    expect(response.status()).toBe(307);
    expect(response.headers().location).toBe(`/search${query}`);
    const context = await browser.newContext({ javaScriptEnabled: false, baseURL });
    try {
      const page = await context.newPage();
      await page.goto(`/${query}`);
      expect(new URL(page.url()).pathname + new URL(page.url()).search).toBe(`/search${query}`);
      await expect(page.getByRole("searchbox")).toHaveValue(new URLSearchParams(query).get("q") ?? "");
    } finally { await context.close(); }
  });
}

